def link_button(text, href, extra=''):
 return f'<a class="button {extra}" href="{href}">{text} {ARROW}</a>'

def img(key,alt,cls='',eager=False):
 source_width = 1660 if key=='hero-classroom' else (1659 if key.startswith('hero') else 1536)
 source_height = 948 if key.startswith('hero') else 1024
 dims = f'{source_width}" height="{source_height}'
 sizes = '100vw' if eager else '(max-width: 700px) 100vw, 60vw'
 return f'<img class="{cls}" src="assets/{key}.webp" srcset="assets/{key}-small.webp 720w, assets/{key}.webp {source_width}w" sizes="{sizes}" width="{dims}" alt="{escape(alt)}" {"fetchpriority=\"high\"" if eager else "loading=\"lazy\""} decoding="async">'

def faq_block(title='A few things you may be wondering.'):
 items=''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in FAQ)
 return f'<section class="section faq-section"><div class="container faq-layout"><div><p class="eyebrow">YOUR QUESTIONS, ANSWERED</p><h2>{title}</h2><a class="text-link" href="contact.html">Speak with admissions {ARROW}</a></div><div class="faq-list">{items}</div></div></section>'

def cta():
 return f'<section class="cta-section"><div class="container cta-inner"><div><p class="eyebrow">YOUR NEXT CHAPTER</p><h2>Let your future<br>take root.</h2></div><div><p>Find a programme that connects your ambition<br class="desktop"> with practical, professional learning.</p>{link_button("Talk to admissions","contact.html")}</div></div></section>'

def heading(label,title,description,image=None):
 if image:
  return f'<section class="page-hero image-page-hero"><div class="container page-hero-grid"><div><nav class="breadcrumb" aria-label="Breadcrumb"><a href="index.html">Home</a><span aria-hidden="true">/</span><span>{label}</span></nav><p class="eyebrow">{label.upper()}</p><h1>{title}</h1><p class="lead">{description}</p></div><div class="page-hero-image">{img(image,"Illustration of practical learning and professional growth")}</div></div></section>'
 return f'<section class="page-hero"><div class="container"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="index.html">Home</a><span aria-hidden="true">/</span><span>{label}</span></nav><p class="eyebrow">{label.upper()}</p><h1>{title}</h1><p class="lead">{description}</p></div></section>'

